228:  *
229:  * If the date is today then "Today" is produced (in the locale language).
230:  * This behavior can be disabled with `noToday: true`.
231:  *
232:  * When time is included, it is appended with a comma and a space. This
233:  * agrees with the output of `Date.prototype.toLocaleString` for *most*
234:  * locales.
235:  *
236:  * @param dateString The date string to parse and format.
237:  * @param options Optional formatting options.
238:  * @returns The formatted date string, or `null` if the input cannot be parsed.
239:  */
240: // TODO: Shouldn't throw on null input
241: export function formatPartialDate(dateString: string, options: Partial<FormatDateOptions> = {}) {
242:   const locale = getLocale();
243:   let parsed: ReturnType<typeof attempt> & { date?: number } = attempt(dateString, locale);
244: 
245:   if (parsed.invalid) {
246:     console.warn(`Could not parse invalid date '${dateString}'`);
247:     return null;
248:   }
249: 
250:   // hack here but any date interprets 2000-01, etc. as yyyy-dd rather than yyyy-mm
251:   if (!isNil(parsed.day) && isNil(parsed.month)) {
252:     parsed = Object.assign({}, omit(parsed, 'day'), { month: parsed.day });
253:   }
254: 
255:   // dayjs' object support uses 0-based months, whereas any-date-parser uses 1-based months
256:   if (parsed.month) {
257:     parsed.month -= 1;
258:   }
259: 
260:   // in dayjs day is day of week; in any-date-parser, its day of month, so we need to convert them
261:   if (parsed.day) {
262:     parsed = Object.assign({}, omit(parsed, 'day'), { date: parsed.day });
263:   }
264: 
265:   const date = dayjs().set(parsed).toDate();
266: 
267:   if (isNil(parsed.year)) {
268:     options.year = false;
269:   }
270: 
271:   if (isNil(parsed.month)) {
272:     options.month = false;
273:   }
274: 
275:   if (isNil(parsed.date)) {
276:     options.day = false;
277:   }
278: 
279:   return formatDate(date, options);
280: }
